        ('mỗi cây khớp y thay vì phần dư', 'from sklearn.tree import DecisionTreeRegressor\ndef fit_gbm(X,y,n,lr,d):\n    f0=float(np.mean(y)); return {"f0":f0,"lr":lr,"trees":[DecisionTreeRegressor(max_depth=d,random_state=0).fit(X,y-f0) for _ in range(n)]}\ndef predict_gbm(m,X):\n    F=np.full(len(X),m["f0"])\n    for t in m["trees"]: F=F+m["lr"]*t.predict(X)\n    return F\ndef staged_mse(m,X,y):\n    F=np.full(len(X),m["f0"]); o=[]\n    for t in m["trees"]: F=F+m["lr"]*t.predict(X); o.append(float(np.mean((y-F)**2)))\n    return np.array(o)\ndef best_n_estimators(m,X,y): return int(np.argmin(staged_mse(m,X,y))+1)'),
