        ('chỉ đặt seed cho NumPy', 'def seed_everything(s): np.random.seed(s)\ndef run_seeds(f,seeds):\n    o=[]\n    for s in seeds: seed_everything(s); o.append(f())\n    return np.array(o)\ndef summarize(x):\n    x=np.asarray(x,float); n=len(x); m,sd=x.mean(),x.std(ddof=1); h=stats.t.ppf(.975,n-1)*sd/math.sqrt(n)\n    return {"mean":float(m),"std":float(sd),"ci_low":float(m-h),"ci_high":float(m+h)}\ndef paired_compare(a,b): return summarize(np.asarray(a)-np.asarray(b))'),
